+            assertThat(secureRandomNonFips.getProvider(), is(notNullValue()));
+            assertThat(secureRandomNonFips.getProvider().getName(), is(equalTo("SUN")));
+            // FIPS DEFAULT/BCFIPS
+            final KeyGenerator keyGeneratorFips = KeyGenerator.getInstance("AES");
